def solve():
    max_s = 0
    for k0 in range(1, 9):
        for k1 in range(1, 9):
            # m is the size of the intersection J0 \cap J1.
            # The sets J0 and J1 are subsets of {1, ..., 8}.
            # |J0| = k0, |J1| = k1, |J0 \cap J1| = m.
            # We must have m <= k0, m <= k1, and k0 + k1 - m <= 8.
            for m in range(max(0, k0 + k1 - 8), min(k0, k1) + 1):
                # A = {f | f_j = 1 for all j in J0}
                # B = {f | f_j = 0 for all j in J1}
                # If m > 0, there exists j \in J0 \cap J1 such that f_j=1 (for f in A)
                # and f_j=0 (for f in B). Thus A \cap B = \emptyset.
                # If m = 0, J0 and J1 are disjoint.
                # A \cap B = {f | f_j = 1 for j \in J0, f_j = 0 for j \in J1}.
                # |A \cap B| = 2^(8 - (k0 + k1)).

                if m > 0:
                    a_cap_b = 0
                else:
                    a_cap_b = 2**(8 - (k0 + k1))

                a_minus_b = 2**(8 - k0) - a_cap_b
                b_minus_a = 2**(8 - k1) - a_cap_b

                limit_h = 2**8 - (a_cap_b + a_minus_b + b_minus_a)

                res = 0
                for h in range(limit_h + 1):
                    g1 = min(a_minus_b, k1 - 1 - h)
                    g0 = min(b_minus_a, k0 - 1 - h)
                    if g1 >= 0 and g0 >= 0:
                        res = max(res, a_cap_b + g1 + g0 + h)
                max_s = max(max_s, res)
    return max_s

